-- =========================================================
-- 1. public.project_share_links
--
-- One owner-controlled share link attached to one existing project.
--
-- Multiple links per project are supported STRUCTURALLY from day one:
-- there is deliberately NO unique constraint on project_id and NO partial
-- unique index restricted to state = 'active'. The V1 product rule of
-- "one active link per project" is a product rule, and it will be enforced
-- transactionally by a future locked owner RPC / server operation, never by
-- a schema restriction that a later multi-link product version would have
-- to destructively migrate away from. This is a locked Phase 1A decision
-- and it supersedes the partial-unique-index recommendation in section
-- 17.2 of the Phase 0 mapping.
--
-- The `state` vocabulary is deliberately five values, not six: rotation
-- does not move a link out of 'active'. A rotated link keeps serving the
-- same curated content under a new secret, so rotation is recorded by
-- rotated_at plus a configuration_version bump (which is what invalidates
-- existing per-link grants), not by a distinct state. Making 'rotated' a
-- state would make every read-time "is this link active" predicate wrong
-- immediately after a rotation. This supersedes the six-value vocabulary
-- suggested in section 17.2 of the Phase 0 mapping.
-- =========================================================

create table public.project_share_links (
  id uuid primary key default gen_random_uuid(),

  user_id uuid not null references auth.users(id) on delete cascade,
  project_id uuid not null references public.projects(id) on delete cascade,

  public_id text not null,

  secret_digest text null,
  secret_digest_version smallint null,

  state text not null default 'draft',

  expires_at timestamptz null,
  comments_enabled boolean not null default false,
  client_facing_subtitle text null,
  content_direction text not null default 'auto',
  configuration_version integer not null default 1,

  last_viewed_at timestamptz null,
  view_count integer not null default 0,

  pin_hash text null,
  pin_salt text null,
  pin_hash_version smallint null,
  pin_scrypt_n integer null,
  pin_scrypt_r integer null,
  pin_scrypt_p integer null,
  pin_key_length integer null,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  activated_at timestamptz null,
  disabled_at timestamptz null,
  rotated_at timestamptz null,
  revoked_at timestamptz null,

  constraint project_share_links_public_id_unique
    unique (public_id),

  -- Opaque, URL-safe, bounded. Never derived from project/client/user data.
  constraint project_share_links_public_id_format_check
    check (public_id ~ '^[A-Za-z0-9_-]{16,64}$'),

  -- Lowercase hex of a keyed HMAC-SHA256 digest. The raw share secret is
  -- never stored in any form, so this column is the ONLY persisted
  -- representation of it and cannot be reversed to recover a lost URL.
  constraint project_share_links_secret_digest_format_check
    check (secret_digest is null or secret_digest ~ '^[0-9a-f]{64}$'),

  -- A secret may be absent only in two cases: the pre-generation 'draft'
  -- state, or a 'revoked' link that reached 'revoked' directly from 'draft'
  -- without ever activating (activated_at is null) -- revoke_share_link
  -- supports revoking a draft outright (an owner discarding an unused link),
  -- and a link that never activated never generated secret material to
  -- begin with, so there is nothing to require here. Every OTHER state --
  -- active, disabled, expired, and a revoked link that WAS previously
  -- activated (activated_at is not null) -- requires a complete, versioned
  -- digest: activation is the only path that ever assigns one, and revoking
  -- an already-activated link must never silently drop its digest history
  -- (revoke_share_link deliberately never clears secret_digest, and the
  -- retained public.project_share_secret_material row would otherwise
  -- reference a link with no corresponding digest evidence at all).
  constraint project_share_links_secret_digest_consistency_check
    check (
      (
        secret_digest is null
        and secret_digest_version is null
        and (
          state = 'draft'
          or (state = 'revoked' and activated_at is null)
        )
      )
      or (
        secret_digest is not null
        and secret_digest_version is not null
        and secret_digest_version > 0
      )
    ),

  constraint project_share_links_state_check
    check (state in ('draft', 'active', 'disabled', 'expired', 'revoked')),

  constraint project_share_links_content_direction_check
    check (content_direction in ('auto', 'ltr', 'rtl')),

  constraint project_share_links_configuration_version_check
    check (configuration_version > 0),

  constraint project_share_links_view_count_check
    check (view_count >= 0),

  constraint project_share_links_client_facing_subtitle_check
    check (
      client_facing_subtitle is null
      or (
        char_length(btrim(client_facing_subtitle)) >= 1
        and char_length(client_facing_subtitle) <= 200
      )
    ),

  -- Lifecycle timestamps can never predate the row, and an expiry can
  -- never be at or before creation.
  constraint project_share_links_timestamp_order_check
    check (
      (activated_at is null or activated_at >= created_at)
      and (disabled_at is null or disabled_at >= created_at)
      and (rotated_at is null or rotated_at >= created_at)
      and (revoked_at is null or revoked_at >= created_at)
      and (last_viewed_at is null or last_viewed_at >= created_at)
      and (expires_at is null or expires_at > created_at)
    ),

  -- Each state carries the lifecycle evidence that state implies. A
  -- previously-disabled link that is re-enabled keeps its disabled_at, so
  -- the 'active' branch deliberately does not forbid a set disabled_at.
  constraint project_share_links_state_lifecycle_check
    check (
      (
        state = 'draft'
        and activated_at is null
        and disabled_at is null
        and revoked_at is null
      )
      or (
        state = 'active'
        and activated_at is not null
        and revoked_at is null
      )
      or (
        state = 'disabled'
        and activated_at is not null
        and disabled_at is not null
        and revoked_at is null
      )
      or (
        state = 'expired'
        and activated_at is not null
        and expires_at is not null
        and revoked_at is null
      )
      or (
        state = 'revoked'
        and revoked_at is not null
      )
    ),

  -- PIN storage is designed for Node crypto.scrypt (Phase 1B+). Explicit
  -- versioned columns rather than an unstructured JSON escape hatch, so
  -- every parameter is individually constrained here and a future cost
  -- increase is a visible schema-level fact, not a silent JSON change.
  -- The fields are either ALL absent or ALL present. Version 1 is a
  -- reviewed fixed profile; a stronger profile must arrive as a new
  -- pin_hash_version in a reviewed migration rather than broad
  -- owner-controlled work-factor ranges.
  constraint project_share_links_pin_completeness_check
    check (
      (
        pin_hash is null
        and pin_salt is null
        and pin_hash_version is null
        and pin_scrypt_n is null
        and pin_scrypt_r is null
        and pin_scrypt_p is null
        and pin_key_length is null
      )
      or (
        pin_hash is not null
        and pin_salt is not null
        and pin_hash_version = 1
        and pin_hash ~ '^[A-Za-z0-9_-]+$'
        and char_length(pin_hash) = 43
        and pin_scrypt_n = 16384
        and pin_scrypt_r = 8
        and pin_scrypt_p = 1
        and pin_key_length = 32
      )
    ),

  -- Both PIN fields are base64url-encoded derived material, never a
  -- plaintext or reversible PIN value, and never a bare SHA-256 of one.
  --
  -- Length is checked with explicit char_length(...) between bounds rather
  -- than a regex repetition count: PostgreSQL's regex engine only supports
  -- repetition bounds up to 255 (SQLSTATE 2201B, "invalid repetition
  -- count(s)", is raised at evaluation time for any bound above that,
  -- including the upper bound of {32,512} this constraint previously
  -- used), so an upper bound of 512 can never be expressed as a regex
  -- bound. The regex itself is retained, anchored and unbounded
  -- (`^[A-Za-z0-9_-]+$`), solely to restrict the character set.
  constraint project_share_links_pin_encoding_check
    check (
      (
        pin_hash is null
        or (
          char_length(pin_hash) between 32 and 512
          and pin_hash ~ '^[A-Za-z0-9_-]+$'
        )
      )
      and (
        pin_salt is null
        or (
          char_length(pin_salt) between 16 and 128
          and pin_salt ~ '^[A-Za-z0-9_-]+$'
        )
      )
    )
);

comment on table public.project_share_links is
  'Owner-controlled Client Share links. Multiple links per project are structurally supported by design: there is deliberately no unique constraint on project_id and no partial unique index on state = ''active''. The V1 one-active-link-per-project product rule is enforced transactionally by a future owner RPC / server operation, never by schema. Never stores a raw or reversible share secret, a plaintext or reversible PIN, a client email/phone, internal client notes, a project amount/priority, or raw input.';

comment on column public.project_share_links.public_id is
  'Opaque, URL-safe public identifier used as the /share/<public_id> path segment. Never derived from project, client or user data, and never a database id. Knowing it alone grants nothing -- it only selects which row a supplied share secret is verified against.';

comment on column public.project_share_links.secret_digest is
  'Lowercase hex keyed HMAC-SHA256 digest of the share secret, computed with a dedicated versioned server secret of at least 32 random bytes. The raw secret is NEVER stored, and no reversible or encrypted copy is stored in V1: a lost share URL is recovered only by rotating the secret and issuing a new URL. Nullable only in the pre-generation ''draft'' state, or a ''revoked'' link that was revoked directly from ''draft'' without ever activating (activated_at is null) -- a link that never activated never generated one. Every other state, including a revoked link that WAS previously activated, requires a complete digest; project_share_links_secret_digest_consistency_check enforces this exactly.';

comment on column public.project_share_links.secret_digest_version is
  'Version of the HMAC key/derivation used for secret_digest, so the server secret can be rotated without invalidating every existing link at once. Required whenever secret_digest is present.';

comment on column public.project_share_links.state is
  'Closed vocabulary: draft, active, disabled, expired, revoked. Rotation deliberately does NOT appear here -- a rotated link stays ''active'' under a new secret, and rotation is recorded by rotated_at plus a configuration_version bump that invalidates existing per-link grants. Read-time checks must always re-verify state, expires_at and the project''s own deleted_at; this column is never the only defence.';

comment on column public.project_share_links.configuration_version is
  'Monotonically increasing version of what this link exposes. A rotation, a disable, comments-enabled changes, or any future curated task/resource/update-set mutation must happen through a transactional owner operation that locks this row and increments this value exactly once before commit. Every share_session_grants row records the version it was granted against, so stale grants are detectable without deleting audit history.';

comment on column public.project_share_links.comments_enabled is
  'Defaults to false: client commenting is opt-in per link, so a link created before the owner has considered the question can never silently accept public writes.';

comment on column public.project_share_links.client_facing_subtitle is
  'Optional owner-authored text shown to the client. Deliberately NOT public.clients.contact_name, .phone, .email or .notes -- no client contact detail is ever copied onto a share link.';

comment on column public.project_share_links.content_direction is
  'Closed vocabulary: auto, ltr, rtl. Per-link text direction for the future public page, chosen because the repository has no i18n framework and no locale detection; ''auto'' means the renderer applies a first-strong-character heuristic.';

comment on column public.project_share_links.pin_hash is
  'Unpadded base64url-encoded derived key from Node crypto.scrypt over the human-entered PIN, using pin_salt and the exact reviewed pin_hash_version 1 profile recorded alongside it: N=16384, r=8, p=1, key_length=32. Version 1 stores a 32-byte derived key as exactly 43 base64url characters. Never a plaintext PIN, never a reversible encoding, and never a bare SHA-256 -- a 4-6 digit PIN is trivially brute-forced against an unsalted fast hash. All PIN columns are either entirely absent or complete and internally consistent (project_share_links_pin_completeness_check).';

comment on column public.project_share_links.pin_salt is
  'Base64url-encoded per-row random salt for pin_hash. Never reused across links and never derived from the PIN, the link, the project or the owner.';

comment on column public.project_share_links.pin_hash_version is
  'Version identifier for the PIN hashing scheme. Version 1 is the reviewed fixed scrypt profile N=16384, r=8, p=1, key_length=32; a future stronger profile requires a new pin_hash_version introduced by a reviewed migration.';

comment on column public.project_share_links.view_count is
  'Non-negative count of public views. Incremented only by the future public projection path; an owner preview must never increment it.';

-- ---------------------------------------------------------
-- Indexes: project_share_links
--
-- Deliberate, one intended query each. No index restricts multiple active
-- links per project, and none duplicates the public_id unique constraint.
--
-- There is deliberately NO index on secret_digest: verification always
-- resolves the row by public_id first and then constant-time compares the
-- digest in server code, so an index on secret_digest would have no query
-- path at all.
-- ---------------------------------------------------------

-- Owner's share-management view for one project ("show me this project's
-- links"), and the ownership pre-check every owner operation performs.
create index project_share_links_user_id_project_id_idx
  on public.project_share_links (user_id, project_id);

-- Owner-wide filtering by lifecycle state ("all my active links"), used by
-- the future management surface and by owner-side counters.
create index project_share_links_user_id_state_idx
  on public.project_share_links (user_id, state);

-- Future expiry sweep that flips still-active but elapsed links to
-- 'expired' and emits a link_expired event. Partial, because a sweep only
-- ever considers active links that actually carry an expiry.
create index project_share_links_expiry_sweep_idx
  on public.project_share_links (expires_at)
  where state = 'active' and expires_at is not null;

-- =========================================================
-- 2. public.share_link_tasks
--
-- The explicit, owner-curated list of subtasks visible through one link.
-- It records only WHICH subtask is visible and HOW it is presented. No
-- task title, status, deadline, amount, priority, raw input, source or
-- client information is copied here -- public.tasks stays the single
-- authoritative source and the public projection reads it at request time.
-- =========================================================

create table public.share_link_tasks (
  id uuid primary key default gen_random_uuid(),

  user_id uuid not null references auth.users(id) on delete cascade,
  share_link_id uuid not null
    references public.project_share_links(id) on delete cascade,
  subtask_id bigint not null references public.tasks(id) on delete cascade,

  public_group text not null,
  waiting_for_client_feedback boolean not null default false,
  display_order integer not null default 0,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint share_link_tasks_share_link_id_subtask_id_unique
    unique (share_link_id, subtask_id),

  constraint share_link_tasks_public_group_check
    check (
      public_group in (
        'in_progress',
        'waiting_for_feedback',
        'completed',
        'coming_up'
      )
    ),

  constraint share_link_tasks_display_order_check
    check (display_order >= 0)
);

comment on table public.share_link_tasks is
  'Explicit owner-curated list of subtasks visible through one share link. Stores only which subtask is visible and how it is presented -- never a copy of task_title, status, deadline, amount, priority, raw_input, source or client information. Cross-owner and cross-project mappings are rejected at the database layer by enforce_share_link_task_integrity (202608030005).';

comment on column public.share_link_tasks.subtask_id is
  'bigint, matching public.tasks.id (the legacy bigint primary key), not uuid. on delete cascade so a hard-deleted task can never remain publicly mapped; note that this repository soft-deletes tasks, so the public projection must ALSO filter tasks.deleted_at is null and tasks.is_archived at read time -- the cascade is a backstop, never the only defence.';

comment on column public.share_link_tasks.public_group is
  'Closed client-facing vocabulary: in_progress, waiting_for_feedback, completed, coming_up. Deliberately NOT the internal status vocabulary (New/In Progress/Review/Urgent/Done) -- ''Urgent'' must never be surfaced publicly, and the internal vocabulary must be free to change without changing what a client sees.';

comment on column public.share_link_tasks.waiting_for_client_feedback is
  'A share-layer presentation flag only. It never reads from, and never writes to, public.tasks.status.';

-- Primary read: one link's curated task list in the owner-chosen order.
create index share_link_tasks_share_link_id_display_order_idx
  on public.share_link_tasks (share_link_id, display_order);

-- Supports the subtask_id FK's cascade and the future "is this subtask
-- shared anywhere?" owner check; without it both are a sequential scan.
create index share_link_tasks_subtask_id_idx
  on public.share_link_tasks (subtask_id);

-- =========================================================
-- 3. public.share_link_resources
--
-- The explicit, owner-curated list of Resources visible through one link.
-- storage_path, file_name, url, mime_type, size_bytes and the internal
-- notes field are deliberately absent: the private task-resources bucket
-- is never exposed or altered, and a public file request resolves a
-- short-lived signed URL server-side at request time instead.
-- =========================================================

create table public.share_link_resources (
  id uuid primary key default gen_random_uuid(),

  user_id uuid not null references auth.users(id) on delete cascade,
  share_link_id uuid not null
    references public.project_share_links(id) on delete cascade,
  resource_id uuid not null
    references public.task_resources(id) on delete cascade,

  public_label text not null,
  can_download boolean not null default false,
  display_order integer not null default 0,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint share_link_resources_share_link_id_resource_id_unique
    unique (share_link_id, resource_id),

  constraint share_link_resources_public_label_check
    check (
      char_length(btrim(public_label)) >= 1
      and char_length(public_label) <= 120
    ),

  constraint share_link_resources_display_order_check
    check (display_order >= 0)
);

comment on table public.share_link_resources is
  'Explicit owner-curated list of Resources visible through one share link. Deliberately stores no storage_path, file_name, url, mime_type, size_bytes or copy of task_resources.notes. The task-resources bucket stays private and is neither exposed nor altered by this feature; public file access resolves a short-lived signed URL server-side per request. Cross-owner and cross-project mappings are rejected by enforce_share_link_resource_integrity (202608030005).';

comment on column public.share_link_resources.public_label is
  'Owner-authored client-facing label. Deliberately a separate column and never task_resources.notes, which is an internal field.';

comment on column public.share_link_resources.resource_id is
  'on delete cascade: public.task_resources rows are HARD deleted by the existing Resources API, so deleting a Resource automatically and immediately revokes client access to it. Already-issued signed URLs still survive until their own short TTL elapses -- that residual window is inherent to signed URLs and is documented in the Phase 1A report.';

comment on column public.share_link_resources.can_download is
  'Defaults to false: download is opt-in per shared Resource, so a Resource shared for viewing can never become downloadable by omission.';

-- Primary read: one link's curated Resource list in the owner-chosen order.
create index share_link_resources_share_link_id_display_order_idx
  on public.share_link_resources (share_link_id, display_order);

-- Supports the resource_id FK's cascade, which fires on every real
-- Resource deletion (Resources are hard deleted in this repository).
create index share_link_resources_resource_id_idx
  on public.share_link_resources (resource_id);

-- =========================================================
-- 4. public.share_link_updates
--
-- Versioned, deliberately published client-facing update text. This is NOT
-- public.project_updates: no raw_input, no ai_summary, no extracted facts,
-- no internal review data and no timeline data ever reaches this table.
-- Published versions are immutable history; publishing writes a NEW row
-- and flips is_current, which is why there is no updated_at column here.
-- =========================================================

create table public.share_link_updates (
  id uuid primary key default gen_random_uuid(),

  user_id uuid not null references auth.users(id) on delete cascade,
  share_link_id uuid not null
    references public.project_share_links(id) on delete cascade,

  body text not null,
  version integer not null,
  published_at timestamptz not null default now(),
  created_by uuid not null references auth.users(id) on delete cascade,
  is_current boolean not null default false,

  created_at timestamptz not null default now(),

  constraint share_link_updates_share_link_id_version_unique
    unique (share_link_id, version),

  constraint share_link_updates_version_check
    check (version > 0),

  constraint share_link_updates_body_check
    check (
      char_length(btrim(body)) >= 1
      and char_length(body) <= 5000
    ),

  constraint share_link_updates_published_at_check
    check (published_at >= created_at)
);

comment on table public.share_link_updates is
  'Versioned, deliberately published client-facing update text for one share link. Never a copy of project_updates.raw_input, project_updates.ai_summary, Client Update facts, internal review data or internal timeline data. Published rows are immutable history -- body, version, published_at and share_link_id cannot be changed after insert (enforce_share_link_update_integrity, 202608030005); publishing a revision inserts a new version and flips is_current.';

comment on column public.share_link_updates.body is
  'Owner-authored client-facing text, immutable once published. Rendered as a text node only -- never as HTML or Markdown with execution semantics.';

comment on column public.share_link_updates.is_current is
  'At most one current version per share link, enforced by the partial unique index below. That restriction is about update versions and has nothing to do with how many links may be active for a project.';

comment on column public.share_link_updates.created_by is
  'The authenticated owner who published this client-facing update. NOT NULL and on delete cascade, matching the single-owner architecture: created_by must equal user_id (enforce_share_link_update_integrity, 202608030005), and deleting the owning account already cascades the owning share link and all update rows.';

-- At most one current published version per link. This is a deliberate
-- partial unique index over update versions -- it is NOT, and must never be
-- confused with, a one-active-link-per-project restriction.
create unique index share_link_updates_current_version_unique_idx
  on public.share_link_updates (share_link_id)
  where is_current;

-- No separate (share_link_id, version) index: the unique constraint above
-- already provides one, and a duplicate would be pure write overhead.

-- =========================================================
-- 5. public.share_messages
--
-- Client comments and owner replies, in a communication stream that is
-- completely and permanently separate from public.project_timeline_events.
-- There is deliberately no foreign key, no trigger and no other structural
-- relationship from this table to the professional project timeline, and
-- no trigger anywhere that mutates projects, tasks, clients, Resources or
-- deadlines when a message is written.
-- =========================================================

create table public.share_messages (
  id uuid primary key default gen_random_uuid(),

  user_id uuid not null references auth.users(id) on delete cascade,
  share_link_id uuid not null
    references public.project_share_links(id) on delete cascade,
  project_id uuid not null references public.projects(id) on delete cascade,

  author_type text not null,
  author_display_name text null,
  body text not null,
  parent_id uuid null references public.share_messages(id) on delete cascade,

  is_visible_to_client boolean not null default true,
  status text not null default 'new',
  reviewed_at timestamptz null,
  resolved_at timestamptz null,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint share_messages_author_type_check
    check (author_type in ('client', 'owner')),

  constraint share_messages_author_display_name_check
    check (
      author_display_name is null
      or (
        char_length(btrim(author_display_name)) >= 1
        and char_length(author_display_name) <= 80
      )
    ),

  constraint share_messages_body_check
    check (
      char_length(btrim(body)) >= 1
      and char_length(body) <= 4000
    ),

  constraint share_messages_status_check
    check (
      status in ('new', 'reviewed', 'resolved', 'dismissed', 'converted')
    ),

  constraint share_messages_status_timestamps_check
    check (
      (reviewed_at is null or reviewed_at >= created_at)
      and (resolved_at is null or resolved_at >= created_at)
      and (
        status = 'new'
        or reviewed_at is not null
      )
      and (
        status <> 'resolved'
        or resolved_at is not null
      )
    ),

  constraint share_messages_no_self_parent_check
    check (parent_id is null or parent_id <> id)
);

comment on table public.share_messages is
  'Client comments and owner replies for one share link. Structurally separate from public.project_timeline_events by design: no foreign key, no trigger and no other relationship to it exists, and no trigger on this table mutates projects, tasks, clients, Resources, deadlines, statuses or priorities. Feedback enters the professional work system only when an authenticated owner deliberately sends it through the existing Client Updates analyze/review/apply flow. Deliberately stores no client email, no client phone, no HTML body and no Markdown-execution field.';

comment on column public.share_messages.project_id is
  'Denormalised from the share link, and enforced equal to it by enforce_share_message_integrity (202608030005). Retained deliberately: the owner''s per-project communication panel and unread counter read by (user_id, project_id) across every link on that project, and carrying project_id here keeps those owner queries a single-table read under RLS while giving every read a third defensive predicate.';

comment on column public.share_messages.author_type is
  'Closed vocabulary: client, owner. An ''owner'' row is only accepted when it is written by the authenticated owner themselves (policy plus enforce_share_message_integrity), and a ''client'' row is accepted only from the service_role public path (enforce_share_message_integrity), so neither side can impersonate the other in a client-visible thread.';

comment on column public.share_messages.body is
  'Plain text only, immutable after insert. The original communication record must survive conversion into a Client Update unchanged -- conversion sets status = ''converted'' and writes a share_message_conversions row, and never rewrites or moves this text.';

comment on column public.share_messages.status is
  'Closed vocabulary: new, reviewed, resolved, dismissed, converted. Owner-side review state only; it never affects what the client can read (is_visible_to_client does that) and never triggers any automatic project, task or CRM change.';

comment on column public.share_messages.parent_id is
  'Self-reference for one threaded conversation. A parent from a different share link, or from a different owner, is rejected by enforce_share_message_integrity. on delete cascade so a removed parent never leaves an orphaned reply addressing nothing.';

-- Primary public/owner thread read for one link, oldest first.
create index share_messages_share_link_id_created_at_idx
  on public.share_messages (share_link_id, created_at);

-- Owner's per-project communication panel across every link on a project,
-- newest first.
create index share_messages_user_id_project_id_created_at_idx
  on public.share_messages (user_id, project_id, created_at desc);

-- Unread-client-feedback counter shown on the owner's project surfaces.
-- Partial, because only unreviewed client messages are ever counted.
create index share_messages_unread_client_idx
  on public.share_messages (user_id, share_link_id)
  where status = 'new' and author_type = 'client';

-- Thread expansion for one parent, and support for the self-FK cascade.
create index share_messages_parent_id_idx
  on public.share_messages (parent_id)
  where parent_id is not null;

-- =========================================================
-- 6. public.share_message_conversions
--
-- Traceability AFTER an authenticated owner has deliberately converted a
-- message through the EXISTING Client Updates workflow. Nothing in this
-- migration analyses a message, creates a project update, creates a task,
-- changes a project or task status, or writes a project timeline row --
-- and no trigger that could do any of those is created anywhere in this
-- migration set.
-- =========================================================

create table public.share_message_conversions (
  id uuid primary key default gen_random_uuid(),

  user_id uuid not null references auth.users(id) on delete cascade,
  message_id uuid not null
    references public.share_messages(id) on delete cascade,
  project_update_id uuid null
    references public.project_updates(id) on delete set null,
  target_task_id bigint null references public.tasks(id) on delete set null,
  converted_by uuid not null references auth.users(id) on delete cascade,

  converted_at timestamptz not null default now(),

  -- Idempotency: at most one conversion record per message. A second
  -- conversion attempt fails loudly on this constraint instead of silently
  -- creating a duplicate trail. A composite (message_id,
  -- project_update_id) key was rejected because project_update_id is
  -- nullable, and NULLs compare as distinct by default, so two rows with a
  -- null project_update_id would both be accepted -- exactly the silent
  -- duplicate this constraint exists to prevent.
  constraint share_message_conversions_message_id_unique
    unique (message_id)
);

comment on table public.share_message_conversions is
  'Traceability record written only AFTER an authenticated owner has deliberately converted a client message through the existing Client Updates analyze/review/apply flow. No trigger analyses a message, creates a project update, creates a task, changes a project/task status, or writes to public.project_timeline_events. One conversion per message (share_message_conversions_message_id_unique).';

comment on column public.share_message_conversions.project_update_id is
  'The existing public.project_updates row the owner produced. Nullable so the record can exist for a conversion that produced no applied update; on delete set null so purging an old Client Update never erases the fact that a client message was acted upon.';

comment on column public.share_message_conversions.target_task_id is
  'bigint, matching public.tasks.id. Optional pointer to the specific subtask the conversion targeted; on delete set null so a removed task never erases the conversion record.';

comment on column public.share_message_conversions.converted_by is
  'The authenticated owner who performed the conversion. Enforced equal to user_id and to auth.uid() by enforce_share_message_conversion_integrity (202608030005), so a conversion can never be attributed to someone who did not perform it.';

-- Owner's "what did I convert, and when" audit read.
create index share_message_conversions_user_id_converted_at_idx
  on public.share_message_conversions (user_id, converted_at desc);

-- Supports the project_update_id FK's on delete set null, and the reverse
-- lookup "which client message produced this Client Update?".
create index share_message_conversions_project_update_id_idx
  on public.share_message_conversions (project_update_id)
  where project_update_id is not null;

-- Supports the target_task_id FK's on delete set null.
create index share_message_conversions_target_task_id_idx
  on public.share_message_conversions (target_task_id)
  where target_task_id is not null;

-- =========================================================
-- 7. updated_at trigger
--
-- One feature-scoped helper shared by every Client Share table that has
-- genuinely mutable state, mirroring public.set_homepage_demo_updated_at()
-- (which is shared across nine homepage-demo tables) rather than creating
-- one near-identical function per table. There is no generic
-- public.set_updated_at() in this repository to reuse -- every existing
-- helper is feature-scoped (set_customer_stories_updated_at,
-- set_homepage_demo_updated_at, set_calendar_events_updated_at), and this
-- follows that established convention exactly.
--
-- Deliberately NOT applied to public.share_link_updates or
-- public.share_message_conversions: both are append-only historical
-- records, so an updated_at column on either would be meaningless at best
-- and misleading at worst. Neither table has one.
--
-- Security posture matches set_calendar_events_updated_at (the newest and
-- strictest existing helper): security invoker plus an explicit
-- search_path, never security definer.
-- =========================================================

create or replace function public.set_client_share_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

comment on function public.set_client_share_updated_at() is
  'Shared updated_at maintenance trigger for Client Share tables with genuinely mutable state. Never applied to append-only tables (share_link_updates, share_message_conversions, share_link_events).';

drop trigger if exists project_share_links_set_updated_at
  on public.project_share_links;

create trigger project_share_links_set_updated_at
before update on public.project_share_links
for each row
execute function public.set_client_share_updated_at();

drop trigger if exists share_link_tasks_set_updated_at
  on public.share_link_tasks;

create trigger share_link_tasks_set_updated_at
before update on public.share_link_tasks
for each row
execute function public.set_client_share_updated_at();

drop trigger if exists share_link_resources_set_updated_at
  on public.share_link_resources;

create trigger share_link_resources_set_updated_at
before update on public.share_link_resources
for each row
execute function public.set_client_share_updated_at();

drop trigger if exists share_messages_set_updated_at
  on public.share_messages;

create trigger share_messages_set_updated_at
before update on public.share_messages
for each row
execute function public.set_client_share_updated_at();

revoke all on function public.set_client_share_updated_at() from public;
revoke all on function public.set_client_share_updated_at() from anon;
revoke all on function public.set_client_share_updated_at() from authenticated;
revoke all on function public.set_client_share_updated_at() from service_role;

-- =========================================================
-- 8. Row Level Security -- owner-facing model
--
-- Every table in this migration is owner-facing, so each gets RLS plus a
-- read policy that EXPLICITLY targets the `authenticated` role.
-- No policy here targets the PostgreSQL PUBLIC role, which is a deliberate
-- tightening over some older tables in this schema whose policies omit the
-- `to` clause and therefore apply to PUBLIC.
--
-- Phase 1A is read-only for authenticated owners at both independent
-- layers: table privileges and RLS policies. Direct owner mutation would
-- bypass the future transactional owner operations that must lock
-- project_share_links, enforce V1 invariants and increment
-- configuration_version exactly once. Phase 1B may add narrow RPC/service
-- operation execution permissions; it must not restore broad direct table
-- DML.
-- =========================================================

alter table public.project_share_links enable row level security;
alter table public.share_link_tasks enable row level security;
alter table public.share_link_resources enable row level security;
alter table public.share_link_updates enable row level security;
alter table public.share_messages enable row level security;
alter table public.share_message_conversions enable row level security;

-- --------------------- project_share_links ---------------------

drop policy if exists "Users can view own project share links"
  on public.project_share_links;

create policy "Users can view own project share links"
  on public.project_share_links
  for select
  to authenticated
  using (auth.uid() = user_id);

-- --------------------- share_link_tasks ---------------------

drop policy if exists "Users can view own share link tasks"
  on public.share_link_tasks;

create policy "Users can view own share link tasks"
  on public.share_link_tasks
  for select
  to authenticated
  using (auth.uid() = user_id);

-- --------------------- share_link_resources ---------------------

drop policy if exists "Users can view own share link resources"
  on public.share_link_resources;

create policy "Users can view own share link resources"
  on public.share_link_resources
  for select
  to authenticated
  using (auth.uid() = user_id);

-- --------------------- share_link_updates ---------------------

drop policy if exists "Users can view own share link updates"
  on public.share_link_updates;

create policy "Users can view own share link updates"
  on public.share_link_updates
  for select
  to authenticated
  using (auth.uid() = user_id);

-- --------------------- share_messages ---------------------

drop policy if exists "Users can view own share messages"
  on public.share_messages;

create policy "Users can view own share messages"
  on public.share_messages
  for select
  to authenticated
  using (auth.uid() = user_id);

-- --------------------- share_message_conversions ---------------------

drop policy if exists "Users can view own share message conversions"
  on public.share_message_conversions;

create policy "Users can view own share message conversions"
  on public.share_message_conversions
  for select
  to authenticated
  using (auth.uid() = user_id);

-- =========================================================
-- 9. Grants -- least privilege
--
-- Supabase's default privileges grant broad table access to anon and
-- authenticated for every new table in the public schema, so these
-- explicit revokes are load-bearing, not decorative. Nothing below grants
-- anything to anon anywhere.
--
-- IMPORTANT: this migration intentionally issues NO positive table grant.
-- Migration 003 can commit safely on its own because every new table stays
-- inaccessible after creation. Positive authenticated/service_role grants
-- are issued only by 202608030005, after all relationship-integrity
-- triggers exist, so no committed intermediate state lets an authenticated
-- user insert rows that reference another tenant's project, task or
-- Resource.
-- =========================================================

revoke all on table public.project_share_links from public;
revoke all on table public.project_share_links from anon;
revoke all on table public.project_share_links from authenticated;
revoke all privileges on table public.project_share_links from service_role;

revoke all on table public.share_link_tasks from public;
revoke all on table public.share_link_tasks from anon;
revoke all on table public.share_link_tasks from authenticated;
revoke all privileges on table public.share_link_tasks from service_role;

revoke all on table public.share_link_resources from public;
revoke all on table public.share_link_resources from anon;
revoke all on table public.share_link_resources from authenticated;
revoke all privileges on table public.share_link_resources from service_role;

revoke all on table public.share_link_updates from public;
revoke all on table public.share_link_updates from anon;
revoke all on table public.share_link_updates from authenticated;
revoke all privileges on table public.share_link_updates from service_role;

revoke all on table public.share_messages from public;
revoke all on table public.share_messages from anon;
revoke all on table public.share_messages from authenticated;
revoke all privileges on table public.share_messages from service_role;

revoke all on table public.share_message_conversions from public;
revoke all on table public.share_message_conversions from anon;
revoke all on table public.share_message_conversions from authenticated;
revoke all privileges
  on table public.share_message_conversions
  from service_role;


-- ===== END 202608030003_client_share_owner_foundation.sql =====

-- Source: supabase/migrations/202608030004_client_share_session_foundation.sql
-- SHA-256 (normalized LF UTF-8): e0cfff71635e32968ee21b7470dafc8075b6ca5b271aaab352af26705a70cdb9
-- ===== BEGIN 202608030004_client_share_session_foundation.sql (verbatim, unmodified) =====

-- Text2Task Client Share Link -- Browser Session, Grant, Event and
-- Rate-Limit Foundation
-- Migration: 202608030004_client_share_session_foundation.sql
-- Created: 2026-08-03
--
-- Purpose:
-- Phase 1A database foundation for everything the anonymous side of the
-- Client Share Link feature needs, none of which is owner-facing. Four
-- tables, all SERVICE-ROLE-ONLY:
--   share_browser_sessions   opaque server-managed browser identities
--   share_session_grants     one grant per (browser session, share link)
--   share_link_events        content-free operational/security audit
--   share_rate_limit_buckets database-atomic rate-limit accounting
--
-- Why sessions and grants are two tables, not one:
-- A single browser must be able to hold access to several independent
-- share links at once. Opening a second shared project must not invalidate
-- access to the first, and disabling, rotating or revoking ONE link must
-- invalidate only that link's grant while leaving unrelated grants in the
-- same browser session untouched. Folding the link into the session row
-- would make both of those impossible: it would force one session row per
-- link (so a second link replaces the first) or one link per session (same
-- outcome). One session with N grants is the only shape that satisfies the
-- locked requirement, and it is what this migration creates.
--
-- Security posture for all four tables (identical to
-- public.authenticated_product_events and the homepage-demo tables):
-- RLS is enabled and NO user-facing policy is defined at all. Combined
-- with the revokes at the bottom of this file that is default-deny for
-- every role, including service_role. Positive service_role grants are
-- deliberately withheld until
-- 202608030005_client_share_integrity_and_security.sql has installed the
-- required integrity trigger on share_session_grants. No anon grant
-- appears anywhere in this migration, no authenticated policy exists on
-- any of these tables, and none of them is exposed through a view.
-- Anonymous clients never query these tables -- a narrowly scoped
-- server-side operation does, after it has verified a browser session and
-- a per-link grant.
--
-- Privacy: no raw browser cookie secret, no raw IP address, no user agent
-- string, no project/task title, no comment body, no client name, no file
-- name, no Resource label, no share secret, no PIN, no public URL, no
-- signed URL and no storage path is stored anywhere in this migration.
-- Identities appear only as versioned keyed digests.
--
-- Non-goals: this migration creates, alters, drops or re-grants no
-- existing production object. public.projects, public.tasks,
-- public.clients, public.users, public.task_resources and storage.* are
-- not touched at all; public.project_share_links is referenced by foreign
-- key only and is not modified.
--
-- Schema-drift posture (fail closed): no `create table if not exists`, no
-- `add column if not exists` and no `create index if not exists` for any
-- new object here. If a Client Share object already exists unexpectedly
-- this migration fails loudly rather than adopting it.
--
-- Transaction posture: no explicit begin;/commit;, matching every existing
-- tracked migration -- see the header of
-- 202608030003_client_share_owner_foundation.sql for the full reasoning.
--
-- Sequencing: this migration must be applied after
-- 202608030003_client_share_owner_foundation.sql (which creates
-- public.project_share_links and public.set_client_share_updated_at) and
-- before 202608030005_client_share_integrity_and_security.sql.

-- =========================================================
-- 1. public.share_browser_sessions
--
-- One row per opaque server-managed browser identity. The browser holds
-- only a random cookie secret; this table holds only a keyed digest of it,
-- so a database leak alone does not yield a usable cookie value.
-- =========================================================

create table public.share_browser_sessions (
  id uuid primary key default gen_random_uuid(),

  session_digest text not null,
  digest_version smallint not null,

  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  last_seen_at timestamptz not null default now(),
  revoked_at timestamptz null,

  constraint share_browser_sessions_session_digest_unique
    unique (session_digest),

  constraint share_browser_sessions_session_digest_format_check
    check (session_digest ~ '^[0-9a-f]{64}$'),

  constraint share_browser_sessions_digest_version_check
    check (digest_version > 0),

  constraint share_browser_sessions_lifecycle_check
    check (
      expires_at > created_at
      and last_seen_at >= created_at
      and (revoked_at is null or revoked_at >= created_at)
    )
);

comment on table public.share_browser_sessions is
  'Opaque server-managed browser session identities for the anonymous Client Share surface. Service-role only: RLS is enabled with no policies at all, and nothing is granted to anon or authenticated. Holds no raw cookie secret, no raw IP, no user agent, and no content of any kind. A session is only an identity -- what it may actually see is decided entirely by its rows in public.share_session_grants.';

comment on column public.share_browser_sessions.session_digest is
  'Lowercase hex keyed digest of the browser''s cookie secret. The raw cookie secret is NEVER stored, so this column cannot be reversed into a working cookie value. Unique, because it is the lookup key for every session resolution.';

comment on column public.share_browser_sessions.digest_version is
  'Version of the keyed digest scheme, so the server key can be rotated without invalidating every live browser session simultaneously.';

comment on column public.share_browser_sessions.revoked_at is
  'Set when a session is deliberately invalidated. Retained rather than deleted so revocation stays auditable; every read path must treat a revoked session as unusable regardless of expires_at.';

-- Expired/revoked browser-session cleanup sweep. Lookup by session_digest
-- is already served by the unique constraint above, so no second index for
-- it is created here.
create index share_browser_sessions_expires_at_idx
  on public.share_browser_sessions (expires_at);

-- =========================================================
-- 2. public.share_session_grants
--
-- One row per (browser session, share link) pair: what this browser is
-- currently allowed to see, and under which configuration version it was
-- granted. Historical revoked grants are preserved. At most one current
-- non-revoked grant may exist for a browser session/link pair, enforced
-- by a partial unique index below rather than a permanent full-pair unique
-- constraint. Deleting a browser session cascades all of its grants;
-- deleting a share link cascades only that link's grants, in every browser
-- session, and touches no other link's grants.
-- =========================================================

create table public.share_session_grants (
  id uuid primary key default gen_random_uuid(),

  browser_session_id uuid not null
    references public.share_browser_sessions(id) on delete cascade,
  share_link_id uuid not null
    references public.project_share_links(id) on delete cascade,

  granted_configuration_version integer not null,
  pin_verified_at timestamptz null,

  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  revoked_at timestamptz null,

  constraint share_session_grants_configuration_version_check
    check (granted_configuration_version > 0),

  constraint share_session_grants_lifecycle_check
    check (
      expires_at > created_at
      and (revoked_at is null or revoked_at >= created_at)
      and (pin_verified_at is null or pin_verified_at >= created_at)
    )
);

comment on table public.share_session_grants is
  'Per-link access grants belonging to one browser session. One browser session may hold grants for many independent share links simultaneously, so opening a second shared project never invalidates access to the first, and disabling/rotating/revoking one link invalidates only that link''s grants. Historical revoked grants are preserved: share_session_grants_current_unique_idx permits at most one non-revoked grant per browser session/link while allowing a future exchange transaction to revoke a stale current grant and insert its replacement atomically. Service-role only: RLS enabled with no policies; all positive access is withheld until 202608030005 installs the integrity trigger and final grants.';

comment on column public.share_session_grants.granted_configuration_version is
  'The project_share_links.configuration_version this grant was issued against. A rotation or configuration change bumps that version, which makes every previously issued grant detectably stale WITHOUT deleting it, so the invalidation is auditable. A read path must compare this against the link''s current configuration_version, never assume it still matches.';

comment on column public.share_session_grants.pin_verified_at is
  'When the PIN for this link was successfully verified in this browser session. Null means "not verified" -- never "no PIN required"; whether a PIN is required is a property of the link, not of the grant.';

comment on column public.share_session_grants.expires_at is
  'Must not exceed the owning browser session''s own expires_at -- enforced by enforce_share_session_grant_integrity (202608030005), because a foreign key cannot express a comparison between two rows.';

comment on column public.share_session_grants.revoked_at is
  'Set when this specific link''s access is withdrawn from this browser session. Retained rather than deleted so revocation stays auditable, and can never be cleared again (enforce_share_session_grant_integrity). A revoked grant must never be treated as active by any read path.';

-- At most one CURRENT grant for this browser session/link pair, while
-- preserving revoked historical rows. A future exchange transaction must
-- lock the existing current grant for the browser session/link, mark it
-- revoked/superseded when it is stale or expired, insert the replacement
-- grant, and commit atomically. An expired-but-not-yet-revoked row still
-- occupies this partial key by design, because expiry alone is not audit
-- revocation.
create unique index share_session_grants_current_unique_idx
  on public.share_session_grants (browser_session_id, share_link_id)
  where revoked_at is null;

-- "Every grant for this link", used by disable/rotate/revoke to withdraw
-- exactly one link's access across all browser sessions, and by the
-- share_link_id FK's cascade. Partial on the live rows those operations
-- actually touch.
create index share_session_grants_share_link_id_active_idx
  on public.share_session_grants (share_link_id)
  where revoked_at is null;

-- Expired-grant cleanup sweep. Current grant lookup by
-- (browser_session_id, share_link_id) is served by the partial unique
-- index above.
create index share_session_grants_expires_at_idx
  on public.share_session_grants (expires_at);

-- =========================================================
-- 3. public.share_link_events
--
-- Content-free operational and security audit trail. Deliberately has no
-- general-purpose metadata JSONB escape hatch: there is no concrete,
-- reviewed requirement for one, and its presence would be a standing
-- invitation to record exactly the content this table exists to keep out.
-- This follows public.authenticated_product_events, which omits a metadata
-- column for the same reason.
-- =========================================================

create table public.share_link_events (
  id uuid primary key default gen_random_uuid(),

  share_link_id uuid not null
    references public.project_share_links(id) on delete cascade,

  event_type text not null,

  identity_digest text null,
  identity_digest_version smallint null,

  created_at timestamptz not null default now(),

  constraint share_link_events_event_type_check
    check (
      event_type in (
        'link_created',
        'link_activated',
        'link_viewed',
        'session_exchanged',
        'pin_failed',
        'comment_submitted',
        'owner_replied',
        'link_disabled',
        'link_rotated',
        'link_expired',
        'link_revoked',
        'shared_resource_opened',
        'rate_limit_triggered'
      )
    ),

  constraint share_link_events_identity_digest_consistency_check
    check (
      (identity_digest is null and identity_digest_version is null)
      or (
        identity_digest is not null
        and identity_digest ~ '^[0-9a-f]{64}$'
        and identity_digest_version is not null
        and identity_digest_version > 0
      )
    )
);

comment on table public.share_link_events is
  'Content-free operational and security audit events for one share link. Records THAT something happened, to WHICH link, and WHEN -- never a project title, task title, comment body, client name, file name, Resource label, share secret, PIN, public URL, signed URL, storage path, raw IP or user agent string. There is deliberately no metadata/jsonb column, so that discipline is structural rather than conventional. Append-only and service-role only: RLS enabled with no policies, nothing granted to anon or authenticated.';

comment on column public.share_link_events.event_type is
  'Closed vocabulary enforced by share_link_events_event_type_check. Adding a value is a deliberate, reviewable migration -- exactly the property that keeps content-free auditing from drifting into content logging.';

comment on column public.share_link_events.identity_digest is
  'Optional lowercase hex keyed HMAC digest of a network identity, mirroring lib/homepage-demo/identity.server.ts. A raw IP address is NEVER stored, and the digest is only ever written together with its version.';

-- Primary audit read: one link's event stream, newest first.
create index share_link_events_share_link_id_created_at_idx
  on public.share_link_events (share_link_id, created_at desc);

-- Retention purge across all links ("delete events older than N days"),
-- which the composite index above cannot serve because its leading column
-- is share_link_id.
create index share_link_events_created_at_idx
  on public.share_link_events (created_at);

-- =========================================================
-- 4. public.share_rate_limit_buckets
--
-- Database-atomic rate-limit accounting for the future public surface:
-- session exchange, PIN verification, projection reads, comment
-- submission, file access, and repeated invalid-link access. Enforcement
-- happens inside a future server operation performing an atomic upsert and
-- increment against the unique bucket key below -- never in application
-- memory, which cannot survive multiple serverless instances.
--
-- The nullable share-link portion of the bucket key, handled deliberately:
-- share_link_id must be nullable, because an invalid-link attempt by
-- definition has no link to attribute. A unique constraint over a nullable
-- column would silently permit unlimited duplicate logical buckets, since
-- SQL treats NULLs as distinct -- so every attacker request would create a
-- brand-new bucket and the limit would never trigger. That failure mode
-- would be invisible until abused. This table therefore derives a STORED
-- generated scope key, share_link_key, which is share_link_id's text form
-- or the literal '-' when there is no link, and the unique constraint uses
-- that key instead of the nullable column. `nulls not distinct` was
-- rejected in favour of the generated key because the generated key is
-- explicit, self-documenting, and does not depend on the Postgres version
-- of the target database.
-- =========================================================

create table public.share_rate_limit_buckets (
  id uuid primary key default gen_random_uuid(),

  scope text not null,
  action text not null,

  identity_digest text not null,
  identity_digest_version smallint not null,

  share_link_id uuid null
    references public.project_share_links(id) on delete cascade,
  share_link_key text not null
    generated always as (coalesce(share_link_id::text, '-')) stored,

  window_start timestamptz not null,
  window_seconds integer not null,
  request_count integer not null default 0,
  expires_at timestamptz not null,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint share_rate_limit_buckets_identity_unique
    unique (
      scope,
      action,
      identity_digest,
      share_link_key,
      window_start,
      window_seconds
    ),

  constraint share_rate_limit_buckets_scope_check
    check (scope in ('browser_session', 'network_identity', 'share_link')),

  constraint share_rate_limit_buckets_action_check
    check (
      action in (
        'session_exchange',
        'pin_verification',
        'projection_read',
        'comment_submission',
        'file_access',
        'invalid_link_access'
      )
    ),

  constraint share_rate_limit_buckets_identity_digest_check
    check (
      identity_digest ~ '^[0-9a-f]{64}$'
      and identity_digest_version > 0
    ),

  -- A share_link-scoped bucket must name its link; an invalid-link attempt
  -- must NOT, because attributing it to a link would require knowing a link
  -- the caller has not proven it may reference.
  constraint share_rate_limit_buckets_share_link_scope_check
    check (scope <> 'share_link' or share_link_id is not null),

  constraint share_rate_limit_buckets_invalid_link_action_check
    check (action <> 'invalid_link_access' or share_link_id is null),

  -- Bounded permitted window durations: one minute, five minutes, one hour,
  -- one day. An unbounded window_seconds would let a single mis-specified
  -- caller create an effectively permanent bucket.
  constraint share_rate_limit_buckets_window_seconds_check
    check (window_seconds in (60, 300, 3600, 86400)),

  constraint share_rate_limit_buckets_request_count_check
    check (request_count >= 0),

  constraint share_rate_limit_buckets_expiry_check
    check (
      expires_at >= window_start + (window_seconds * interval '1 second')
    )
);

comment on table public.share_rate_limit_buckets is
  'Database-atomic rate-limit accounting for the future anonymous Client Share surface. Service-role only: RLS enabled with no policies, nothing granted to anon or authenticated. Stores no raw IP address and no content -- identities appear only as versioned keyed digests.';

comment on column public.share_rate_limit_buckets.share_link_key is
  'STORED generated bucket-key component: share_link_id::text, or the literal ''-'' when there is no link (an invalid-link attempt). It exists solely so the unique bucket identity below can never be defeated by SQL''s NULL-is-distinct rule, which would otherwise let every invalid-link request mint a fresh bucket and silently disable the limit. Never written directly.';

comment on column public.share_rate_limit_buckets.scope is
  'Closed vocabulary: browser_session, network_identity, share_link. Combining a link-scoped bucket with an identity-scoped bucket is the intended enforcement shape, so neither alone is sufficient to pass.';

comment on column public.share_rate_limit_buckets.action is
  'Closed vocabulary: session_exchange, pin_verification, projection_read, comment_submission, file_access, invalid_link_access.';

comment on column public.share_rate_limit_buckets.identity_digest is
  'Lowercase hex keyed HMAC digest of the browser session, network identity or link-scoped identity being limited. A raw IP address is NEVER stored.';

-- Expired-bucket purge. The unique constraint above already serves the
-- atomic upsert/increment lookup, so no second index for it is created.
create index share_rate_limit_buckets_expires_at_idx
  on public.share_rate_limit_buckets (expires_at);

-- Supports the share_link_id FK's cascade when a share link row is
-- deleted; the unique constraint's index leads with scope and cannot serve
-- it.
create index share_rate_limit_buckets_share_link_id_idx
  on public.share_rate_limit_buckets (share_link_id)
  where share_link_id is not null;

-- request_count is genuinely mutable (every increment rewrites the row),
-- so this table gets the shared Client Share updated_at trigger created in
-- 202608030003. The other three tables in this migration are append-only
-- apart from explicit lifecycle timestamps and deliberately have no
-- updated_at column at all.
drop trigger if exists share_rate_limit_buckets_set_updated_at
  on public.share_rate_limit_buckets;

create trigger share_rate_limit_buckets_set_updated_at
before update on public.share_rate_limit_buckets
for each row
execute function public.set_client_share_updated_at();

-- =========================================================
-- 5. Row Level Security -- service-role-only model
--
-- RLS is enabled on all four tables and NO policy of any kind is created.
-- With the grants below that is default-deny for public, anon and
-- authenticated: an authenticated application user cannot read even a row
-- that ultimately concerns their own share link through PostgREST, and an
-- anonymous caller cannot reach these tables at all.
-- =========================================================

alter table public.share_browser_sessions enable row level security;
alter table public.share_session_grants enable row level security;
alter table public.share_link_events enable row level security;
alter table public.share_rate_limit_buckets enable row level security;

-- =========================================================
-- 6. Grants -- least privilege, service_role only
--
-- Supabase's default privileges grant broad table access to anon and
-- authenticated for every new public-schema table, so these revokes are
-- load-bearing. Nothing here is granted to anon or authenticated, and this
-- migration intentionally issues NO positive service_role table grant.
-- Positive service_role grants are issued only by 202608030005 after the
-- share_session_grants integrity trigger exists, so migration 004 can
-- commit safely on its own.
-- =========================================================

revoke all on table public.share_browser_sessions from public;
revoke all on table public.share_browser_sessions from anon;
revoke all on table public.share_browser_sessions from authenticated;
revoke all privileges
  on table public.share_browser_sessions
  from service_role;

revoke all on table public.share_session_grants from public;
revoke all on table public.share_session_grants from anon;
revoke all on table public.share_session_grants from authenticated;
revoke all privileges
  on table public.share_session_grants
  from service_role;

revoke all on table public.share_link_events from public;
revoke all on table public.share_link_events from anon;
revoke all on table public.share_link_events from authenticated;
revoke all privileges
  on table public.share_link_events
  from service_role;

revoke all on table public.share_rate_limit_buckets from public;
revoke all on table public.share_rate_limit_buckets from anon;
revoke all on table public.share_rate_limit_buckets from authenticated;
revoke all privileges
  on table public.share_rate_limit_buckets
  from service_role;


-- ===== END 202608030004_client_share_session_foundation.sql =====

-- Source: supabase/migrations/202608030005_client_share_integrity_and_security.sql
-- SHA-256 (normalized LF UTF-8): 1574b6ea45218219751e70fbbbe32ac8636e090f6955631449829a4ac1edc12d
-- ===== BEGIN 202608030005_client_share_integrity_and_security.sql (verbatim, unmodified) =====

-- Text2Task Client Share Link -- Cross-Table Integrity and Privilege
-- Hardening
-- Migration: 202608030005_client_share_integrity_and_security.sql
-- Created: 2026-08-03
--
-- Purpose:
-- Phase 1A database-level relationship integrity for the Client Share
-- Link feature. Row Level Security on a Client Share row can only ever
-- express "this row's user_id is me". It structurally cannot express "the
-- project, task, Resource, Client Update or parent message this row points
-- at belongs to the same owner and the same project" -- no RLS policy
-- anywhere in this repository joins to a parent table, and none should
-- start. Application-level checks alone are also insufficient: they are
-- re-derived at every call site, and the service role bypasses RLS
-- entirely.
--
-- This migration therefore adds one narrowly scoped trigger per Client
-- Share table that carries a cross-table relationship, following the
-- pattern established by
-- public.enforce_calendar_event_relationship_integrity() in
-- 202607290001_calendar_events.sql exactly: language plpgsql, SECURITY
-- INVOKER, an explicit `set search_path = public, pg_temp`, and stable
-- SCREAMING_SNAKE_CASE messages raised with errcode P0001 so TypeScript
-- can match them the way app/api/projects/update/route.ts already matches
-- existing database error codes.
--
-- Deliberate behavioural rules, all of which differ from the calendar
-- precedent and are the safer choice here:
--   - NOTHING is silently repaired or normalised. The calendar trigger
--     normalises client_id to the linked project's client. These triggers
--     never rewrite an input value; a mismatched user_id/project_id pair
--     is REJECTED, never quietly corrected, because quietly correcting it
--     would hide invalid caller input on a surface whose whole purpose is
--     deciding what a third party may see.
--   - No cross-tenant fallback of any kind exists. Every check compares
--     against the row's own user_id and the share link's own project_id.
--   - The conversion traceability trigger is INSERT-only, so FK-driven
--     ON DELETE SET NULL maintenance can still clear optional target
--     references without user-facing UPDATE capability.
--   - No trigger here analyses a message, creates a project update,
--     creates a task, changes a project or task status, mutates any CRM
--     row, or writes to public.project_timeline_events. There is
--     deliberately no automatic message-to-CRM path anywhere in this
--     migration set.
--
-- SECURITY DEFINER is NOT used anywhere in this migration. Every function
-- is SECURITY INVOKER, matching all but one function in the entire
-- existing schema. Under an owner-authenticated caller, RLS on
-- public.projects / public.tasks / public.task_resources means a
-- cross-account id simply resolves to "not found" rather than "not owned";
-- both outcomes reject the write, which is the required behaviour. Under
-- the service role, RLS is bypassed and the explicit ownership comparisons
-- below are what actually enforce the boundary -- which is precisely why
-- they are written as explicit comparisons rather than relying on RLS.
--
-- Non-goals: this migration creates, alters, drops or re-grants no
-- existing production object. public.projects, public.tasks,
-- public.clients, public.task_resources, public.project_updates and
-- storage.* are read inside function bodies only, never modified. The two
-- overlapping public.task_resources resource_type CHECK constraints are
-- deliberately left exactly as they are.
--
-- Schema-drift posture (fail closed): this migration creates no table, no
-- column and no index. `create or replace function` and `drop trigger if
-- exists` are used only where the full intended definition is supplied
-- immediately below in this file.
--
-- Transaction posture: no explicit begin;/commit;, matching every existing
-- tracked migration -- see the header of
-- 202608030003_client_share_owner_foundation.sql for the full reasoning.
--
-- Sequencing: apply after 202608030003_client_share_owner_foundation.sql
-- and 202608030004_client_share_session_foundation.sql, both of which must
-- already have created every table referenced here.

-- =========================================================
-- 1. public.project_share_links
--
-- A link may only ever be attached to a project the link's own user_id
-- owns, and a link's owner may never be reassigned. The project's owner is
-- deliberately NOT copied into new.user_id: copying it would silently
-- accept -- and then hide -- a caller that supplied the wrong user_id.
-- =========================================================

create or replace function public.enforce_project_share_link_integrity()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_project_user_id uuid;
  v_access_changed boolean;
  v_digest_changed boolean;
  v_secret_changed boolean;
  v_rotation_timestamp_changed boolean;
  v_state_transition_allowed boolean;
begin
  if tg_op = 'UPDATE' then
    if new.user_id is distinct from old.user_id then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_OWNER_MISMATCH';
    end if;

    if new.project_id is distinct from old.project_id then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_PROJECT_IMMUTABLE';
    end if;

    if new.public_id is distinct from old.public_id then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_PUBLIC_ID_IMMUTABLE';
    end if;

    if new.created_at is distinct from old.created_at then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_CREATED_AT_IMMUTABLE';
    end if;

    if old.activated_at is not null
      and new.activated_at is distinct from old.activated_at then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_ACTIVATED_AT_IMMUTABLE';
    end if;

    if old.state <> 'draft' and new.state = 'draft' then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_DRAFT_STATE_IRREVERSIBLE';
    end if;

    if old.disabled_at is not null
      and (
        new.disabled_at is null
        or new.disabled_at < old.disabled_at
      ) then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_DISABLED_AT_DECREASE';
    end if;

    if old.rotated_at is not null
      and (
        new.rotated_at is null
        or new.rotated_at < old.rotated_at
      ) then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_ROTATED_AT_DECREASE';
    end if;

    if new.configuration_version < old.configuration_version then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_CONFIGURATION_VERSION_DECREASE';
    end if;

    if new.view_count < old.view_count then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_VIEW_COUNT_DECREASE';
    end if;

    if old.last_viewed_at is not null
      and (
        new.last_viewed_at is null
        or new.last_viewed_at < old.last_viewed_at
      ) then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_LAST_VIEWED_AT_DECREASE';
    end if;

    if old.revoked_at is not null
      and (
        new.revoked_at is null
        or new.revoked_at < old.revoked_at
      ) then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_REVOCATION_IRREVERSIBLE';
    end if;

    if old.state = 'revoked' and new.state <> 'revoked' then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_REVOKED_STATE_TERMINAL';
    end if;

    if new.state is distinct from old.state then
      v_state_transition_allowed :=
        (old.state = 'draft' and new.state in ('active', 'revoked'))
        or (old.state = 'active' and new.state in ('disabled', 'expired', 'revoked'))
        or (old.state = 'disabled' and new.state in ('active', 'expired', 'revoked'))
        or (old.state = 'expired' and new.state in ('active', 'revoked'));

      if not v_state_transition_allowed then
        raise exception using errcode = 'P0001', message = 'SHARE_LINK_STATE_TRANSITION_INVALID';
      end if;

      if old.state = 'expired'
        and new.state = 'active'
        and new.configuration_version <= old.configuration_version then
        raise exception using errcode = 'P0001', message = 'SHARE_LINK_VERSION_NOT_INCREMENTED';
      end if;
    end if;

    v_access_changed :=
      new.secret_digest is distinct from old.secret_digest
      or new.secret_digest_version is distinct from old.secret_digest_version
      or new.state is distinct from old.state
      or new.expires_at is distinct from old.expires_at
      or new.pin_hash is distinct from old.pin_hash
      or new.pin_salt is distinct from old.pin_salt
      or new.pin_hash_version is distinct from old.pin_hash_version
      or new.pin_scrypt_n is distinct from old.pin_scrypt_n
      or new.pin_scrypt_r is distinct from old.pin_scrypt_r
      or new.pin_scrypt_p is distinct from old.pin_scrypt_p
      or new.pin_key_length is distinct from old.pin_key_length
      or new.comments_enabled is distinct from old.comments_enabled
      or new.client_facing_subtitle is distinct from old.client_facing_subtitle
      or new.content_direction is distinct from old.content_direction;

    if v_access_changed and new.configuration_version <= old.configuration_version then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_VERSION_NOT_INCREMENTED';
    end if;

    v_digest_changed := new.secret_digest is distinct from old.secret_digest;
    v_secret_changed :=
      v_digest_changed
      or new.secret_digest_version is distinct from old.secret_digest_version;
    v_rotation_timestamp_changed := new.rotated_at is distinct from old.rotated_at;

    if new.secret_digest_version is distinct from old.secret_digest_version
      and not v_digest_changed then
      raise exception using errcode = 'P0001', message = 'SHARE_LINK_ROTATION_REQUIRES_SECRET_CHANGE';
    end if;

    if old.secret_digest is not null and v_secret_changed then
      if new.rotated_at is null
        or new.rotated_at is not distinct from old.rotated_at
        or (
          old.rotated_at is not null
          and new.rotated_at <= old.rotated_at
        ) then
        raise exception using errcode = 'P0001', message = 'SHARE_LINK_ROTATION_TIMESTAMP_REQUIRED';
      end if;
    end if;

    if v_rotation_timestamp_changed then
      if new.rotated_at is null
        or (
          old.rotated_at is not null
          and new.rotated_at <= old.rotated_at
        ) then
        raise exception using errcode = 'P0001', message = 'SHARE_LINK_ROTATION_TIMESTAMP_REQUIRED';
      end if;

      if not v_digest_changed then
        raise exception using errcode = 'P0001', message = 'SHARE_LINK_ROTATION_REQUIRES_SECRET_CHANGE';
      end if;

      if new.configuration_version <= old.configuration_version then
        raise exception using errcode = 'P0001', message = 'SHARE_LINK_VERSION_NOT_INCREMENTED';
      end if;
    end if;
  end if;

  select project.user_id
    into v_project_user_id
    from public.projects as project
    where project.id = new.project_id;

  if v_project_user_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_LINK_PROJECT_NOT_FOUND';
  end if;

  if v_project_user_id <> new.user_id then
    raise exception using errcode = 'P0001', message = 'SHARE_LINK_PROJECT_NOT_OWNED';
  end if;

  return new;
end;
$$;

comment on function public.enforce_project_share_link_integrity() is
  'Rejects a share link whose project_id is not owned by the link''s own user_id; rejects owner, project, public_id and created_at reassignment; enforces monotonic configuration_version, view_count, last_viewed_at and revoked_at; makes revoked state terminal; and requires security/access changes to increase configuration_version. Never copies or silently repairs caller input.';

drop trigger if exists project_share_links_enforce_integrity
  on public.project_share_links;

create trigger project_share_links_enforce_integrity
before insert or update on public.project_share_links
for each row
execute function public.enforce_project_share_link_integrity();

-- =========================================================
-- 2. public.share_link_tasks
--
-- Every mapping must satisfy all of: the mapping's user_id equals the
-- share link's user_id; the referenced task belongs to that same user; the
-- task belongs to the SAME project as the share link; the task actually
-- has a project. A cross-account subtask id and a same-owner but
-- cross-project subtask id are both rejected, with distinct stable codes.
--
-- A soft-deleted task is rejected at mapping time as well. That is not a
-- substitute for read-time filtering: this repository soft-deletes tasks,
-- so a task deleted AFTER it was mapped still needs
-- `tasks.deleted_at is null` (and an archived check) in every public read.
-- Deleted/archived state is never copied into the mapping -- this table
-- has no column that could hold it.
-- =========================================================

create or replace function public.enforce_share_link_task_integrity()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_link_user_id uuid;
  v_link_project_id uuid;
  v_task_user_id uuid;
  v_task_project_id uuid;
  v_task_deleted_at timestamptz;
  v_relationship_changed boolean;
begin
  if tg_op = 'INSERT' then
    v_relationship_changed := true;
  else
    v_relationship_changed :=
      new.user_id is distinct from old.user_id
      or new.share_link_id is distinct from old.share_link_id
      or new.subtask_id is distinct from old.subtask_id;
  end if;

  if not v_relationship_changed then
    return new;
  end if;

  select link.user_id, link.project_id
    into v_link_user_id, v_link_project_id
    from public.project_share_links as link
    where link.id = new.share_link_id;

  if v_link_user_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_TASK_LINK_NOT_FOUND';
  end if;

  if v_link_user_id <> new.user_id then
    raise exception using errcode = 'P0001', message = 'SHARE_TASK_OWNER_MISMATCH';
  end if;

  select task.user_id, task.project_id, task.deleted_at
    into v_task_user_id, v_task_project_id, v_task_deleted_at
    from public.tasks as task
    where task.id = new.subtask_id;

  if v_task_user_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_TASK_NOT_FOUND';
  end if;

  if v_task_user_id <> new.user_id then
    raise exception using errcode = 'P0001', message = 'SHARE_TASK_NOT_OWNED';
  end if;

  if v_task_deleted_at is not null then
    raise exception using errcode = 'P0001', message = 'SHARE_TASK_DELETED';
  end if;

  if v_task_project_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_TASK_WITHOUT_PROJECT';
  end if;

  if v_task_project_id <> v_link_project_id then
    raise exception using errcode = 'P0001', message = 'SHARE_TASK_PROJECT_MISMATCH';
  end if;

  return new;
end;
$$;

comment on function public.enforce_share_link_task_integrity() is
  'Rejects any share-link task mapping whose owner does not match the link''s owner, whose task is not owned by that same user, whose task has no project, whose task belongs to a different project than the link, or whose task is soft-deleted. Cross-account and same-owner-cross-project subtask ids are rejected with distinct stable codes.';

drop trigger if exists share_link_tasks_enforce_integrity
  on public.share_link_tasks;

create trigger share_link_tasks_enforce_integrity
before insert or update on public.share_link_tasks
for each row
execute function public.enforce_share_link_task_integrity();

-- =========================================================
-- 3. public.share_link_resources
--
-- public.task_resources rows may hang off a project directly, off a task,
-- or off both. All three cases must resolve to the SAME project as the
-- share link:
--   - a direct project Resource is allowed only when
--     resource.project_id equals link.project_id;
--   - a task Resource is allowed only when its task belongs to the same
--     owner AND that task's project_id equals link.project_id;
--   - when both project_id and task_id are populated they must not
--     contradict each other;
--   - a Resource with neither cannot be proven to belong to the link's
--     project at all and is rejected rather than assumed safe.
-- =========================================================

create or replace function public.enforce_share_link_resource_integrity()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_link_user_id uuid;
  v_link_project_id uuid;
  v_resource_user_id uuid;
  v_resource_project_id uuid;
  v_resource_task_id bigint;
  v_task_user_id uuid;
  v_task_project_id uuid;
  v_relationship_changed boolean;
begin
  if tg_op = 'INSERT' then
    v_relationship_changed := true;
  else
    v_relationship_changed :=
      new.user_id is distinct from old.user_id
      or new.share_link_id is distinct from old.share_link_id
      or new.resource_id is distinct from old.resource_id;
  end if;

  if not v_relationship_changed then
    return new;
  end if;

  select link.user_id, link.project_id
    into v_link_user_id, v_link_project_id
    from public.project_share_links as link
    where link.id = new.share_link_id;

  if v_link_user_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_RESOURCE_LINK_NOT_FOUND';
  end if;

  if v_link_user_id <> new.user_id then
    raise exception using errcode = 'P0001', message = 'SHARE_RESOURCE_OWNER_MISMATCH';
  end if;

  select resource.user_id, resource.project_id, resource.task_id
    into v_resource_user_id, v_resource_project_id, v_resource_task_id
    from public.task_resources as resource
    where resource.id = new.resource_id;

  if v_resource_user_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_RESOURCE_NOT_FOUND';
  end if;

  if v_resource_user_id <> new.user_id then
    raise exception using errcode = 'P0001', message = 'SHARE_RESOURCE_NOT_OWNED';
  end if;

  if v_resource_project_id is null and v_resource_task_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_RESOURCE_RELATIONSHIP_INVALID';
  end if;

  if v_resource_project_id is not null
    and v_resource_project_id <> v_link_project_id then
    raise exception using errcode = 'P0001', message = 'SHARE_RESOURCE_PROJECT_MISMATCH';
  end if;

  if v_resource_task_id is not null then
    select task.user_id, task.project_id
      into v_task_user_id, v_task_project_id
      from public.tasks as task
      where task.id = v_resource_task_id;

    if v_task_user_id is null then
      raise exception using errcode = 'P0001', message = 'SHARE_RESOURCE_RELATIONSHIP_INVALID';
    end if;

    if v_task_user_id <> new.user_id then
      raise exception using errcode = 'P0001', message = 'SHARE_RESOURCE_NOT_OWNED';
    end if;

    if v_task_project_id is null
      or v_task_project_id <> v_link_project_id then
      raise exception using errcode = 'P0001', message = 'SHARE_RESOURCE_TASK_PROJECT_MISMATCH';
    end if;

    if v_resource_project_id is not null
      and v_resource_project_id <> v_task_project_id then
      raise exception using errcode = 'P0001', message = 'SHARE_RESOURCE_RELATIONSHIP_INVALID';
    end if;
  end if;

  return new;
end;
$$;

comment on function public.enforce_share_link_resource_integrity() is
  'Rejects any share-link Resource mapping whose owner does not match the link''s owner, whose Resource is not owned by that same user, whose Resource belongs to a different project than the link, whose task-attached Resource hangs off a task in a different project, whose project_id and task_id contradict each other, or which can be attributed to no project at all. Cross-account and same-owner-cross-project Resource ids are rejected.';

drop trigger if exists share_link_resources_enforce_integrity
  on public.share_link_resources;

create trigger share_link_resources_enforce_integrity
before insert or update on public.share_link_resources
for each row
execute function public.enforce_share_link_resource_integrity();

-- =========================================================
-- 4. public.share_link_updates
--
-- The owner must match the share link's owner, created_by must be that
-- same owner, and a published version is immutable
-- afterwards: only is_current may ever change. version > 0 is already a
-- CHECK constraint on the table and is deliberately not re-implemented
-- here -- a constraint is the right tool for a single-column invariant,
-- and duplicating it in a trigger would create two places to change it.
-- =========================================================

create or replace function public.enforce_share_link_update_integrity()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_link_user_id uuid;
begin
  if tg_op = 'UPDATE' then
    if new.share_link_id is distinct from old.share_link_id
      or new.user_id is distinct from old.user_id
      or new.body is distinct from old.body
      or new.version is distinct from old.version
      or new.published_at is distinct from old.published_at
      or new.created_by is distinct from old.created_by
      or new.created_at is distinct from old.created_at then
      raise exception using errcode = 'P0001', message = 'SHARE_UPDATE_IMMUTABLE';
    end if;

    return new;
  end if;

  select link.user_id
    into v_link_user_id
    from public.project_share_links as link
    where link.id = new.share_link_id;

  if v_link_user_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_UPDATE_LINK_NOT_FOUND';
  end if;

  if v_link_user_id <> new.user_id then
    raise exception using errcode = 'P0001', message = 'SHARE_UPDATE_OWNER_MISMATCH';
  end if;

  if new.created_by <> new.user_id then
    raise exception using errcode = 'P0001', message = 'SHARE_UPDATE_CREATED_BY_MISMATCH';
  end if;

  return new;
end;
$$;

comment on function public.enforce_share_link_update_integrity() is
  'Rejects a published client-facing update whose owner does not match the share link''s owner or whose created_by is a different user, and makes a published version immutable afterwards -- only is_current may change, so the current-version pointer can move without ever rewriting published history.';

drop trigger if exists share_link_updates_enforce_integrity
  on public.share_link_updates;

create trigger share_link_updates_enforce_integrity
before insert or update on public.share_link_updates
for each row
execute function public.enforce_share_link_update_integrity();

-- =========================================================
-- 5. public.share_messages
--
-- The owner must match the share link's owner; the denormalised project_id
-- must match the link's project; a parent message must belong to the SAME
-- share link and the same owner; an owner-authored message must actually
-- be written by that authenticated owner; and a client-authored message
-- must be written through the service_role public path to an active,
-- unexpired, comments-enabled link on a live project. Browser-session and
-- per-link grant validation remains in the public server operation
-- because share_messages deliberately stores no browser-session id.
--
-- The message body, author identity and thread position are immutable
-- after insert: the original communication record must survive review and
-- conversion unchanged. Only the review/visibility lifecycle
-- (is_visible_to_client, status, reviewed_at, resolved_at, updated_at) may
-- change.
--
-- This function writes to nothing. It contains no insert, update or delete
-- against any table, and specifically none against
-- public.project_timeline_events, public.projects, public.tasks,
-- public.clients, public.task_resources or public.project_updates.
-- =========================================================

create or replace function public.enforce_share_message_integrity()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_link_user_id uuid;
  v_link_project_id uuid;
  v_link_state text;
  v_link_comments_enabled boolean;
  v_link_expires_at timestamptz;
  v_project_id uuid;
  v_project_deleted_at timestamptz;
  v_parent_share_link_id uuid;
  v_parent_user_id uuid;
  v_parent_is_visible_to_client boolean;
begin
  if tg_op = 'UPDATE' then
    if new.share_link_id is distinct from old.share_link_id
      or new.user_id is distinct from old.user_id
      or new.project_id is distinct from old.project_id
      or new.parent_id is distinct from old.parent_id
      or new.author_type is distinct from old.author_type
      or new.author_display_name is distinct from old.author_display_name
      or new.body is distinct from old.body
      or new.created_at is distinct from old.created_at then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_IMMUTABLE';
    end if;

    return new;
  end if;

  select
      link.user_id,
      link.project_id,
      link.state,
      link.comments_enabled,
      link.expires_at,
      project.id,
      project.deleted_at
    into
      v_link_user_id,
      v_link_project_id,
      v_link_state,
      v_link_comments_enabled,
      v_link_expires_at,
      v_project_id,
      v_project_deleted_at
    from public.project_share_links as link
    left join public.projects as project
      on project.id = link.project_id
    where link.id = new.share_link_id;

  if v_link_user_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_LINK_NOT_FOUND';
  end if;

  if v_link_user_id <> new.user_id then
    raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_OWNER_MISMATCH';
  end if;

  if new.project_id <> v_link_project_id then
    raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_PROJECT_MISMATCH';
  end if;

  if new.author_type = 'owner' then
    if auth.uid() is distinct from new.user_id then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_OWNER_AUTHOR_NOT_AUTHENTICATED';
    end if;
  elsif new.author_type = 'client' then
    if current_role <> 'service_role' then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_AUTHOR_REQUIRES_SERVICE_ROLE';
    end if;

    if v_link_state <> 'active' then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_LINK_NOT_ACTIVE';
    end if;

    if not v_link_comments_enabled then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_COMMENTS_DISABLED';
    end if;

    if v_link_expires_at is not null and v_link_expires_at <= now() then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_LINK_EXPIRED';
    end if;

    if v_project_id is null then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_PROJECT_NOT_FOUND';
    end if;

    if v_project_deleted_at is not null then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_PROJECT_DELETED';
    end if;

    if new.status <> 'new' then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_STATUS_INVALID';
    end if;

    if new.reviewed_at is not null then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_REVIEWED_AT_FORBIDDEN';
    end if;

    if new.resolved_at is not null then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_RESOLVED_AT_FORBIDDEN';
    end if;

    if new.is_visible_to_client is not true then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_VISIBILITY_INVALID';
    end if;
  else
    raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_AUTHOR_TYPE_INVALID';
  end if;

  if new.parent_id is not null then
    select parent.share_link_id, parent.user_id, parent.is_visible_to_client
      into v_parent_share_link_id, v_parent_user_id, v_parent_is_visible_to_client
      from public.share_messages as parent
      where parent.id = new.parent_id;

    if v_parent_share_link_id is null then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_PARENT_NOT_FOUND';
    end if;

    if v_parent_share_link_id <> new.share_link_id then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_PARENT_LINK_MISMATCH';
    end if;

    if v_parent_user_id <> new.user_id then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_PARENT_OWNER_MISMATCH';
    end if;

    if new.author_type = 'client'
      and v_parent_is_visible_to_client is not true then
      raise exception using errcode = 'P0001', message = 'SHARE_MESSAGE_CLIENT_PARENT_NOT_VISIBLE';
    end if;
  end if;

  return new;
end;
$$;

comment on function public.enforce_share_message_integrity() is
  'Rejects a share message whose owner or project does not match its share link, whose parent belongs to a different link or owner, whose author_type = ''owner'' was not written by that authenticated owner, or whose author_type = ''client'' was not written through service_role as a fresh visible client message with no owner-review state on an active, unexpired, comments-enabled link whose project exists and is not soft-deleted. Client replies may reference only client-visible parent messages. Writes to no table: no CRM mutation and no public.project_timeline_events row is ever produced by a client comment or an owner reply.';

drop trigger if exists share_messages_enforce_integrity
  on public.share_messages;

create trigger share_messages_enforce_integrity
before insert or update on public.share_messages
for each row
execute function public.enforce_share_message_integrity();

-- =========================================================
-- 6. public.share_message_conversions
--
-- Traceability only, written after the fact. The converting actor must be
-- the authenticated owner of the message, and any referenced Client Update
-- or task must belong to that same owner AND to the same project as the
-- share link the message came from (the message's project_id is itself
-- enforced equal to the link's project by enforce_share_message_integrity
-- above, so comparing against it is equivalent to comparing against the
-- link and avoids a second lookup).
--
-- This function performs no conversion. It creates nothing, analyses
-- nothing and changes no project, task or status. Its trigger is INSERT
-- only: authenticated owners have no UPDATE grant or policy on conversion
-- rows, and FK-driven ON DELETE SET NULL cleanup of optional targets must
-- remain possible.
-- =========================================================

create or replace function public.enforce_share_message_conversion_integrity()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_message_user_id uuid;
  v_message_project_id uuid;
  v_message_author_type text;
  v_update_user_id uuid;
  v_update_project_id uuid;
  v_task_user_id uuid;
  v_task_project_id uuid;
begin
  select message.user_id, message.project_id, message.author_type
    into v_message_user_id, v_message_project_id, v_message_author_type
    from public.share_messages as message
    where message.id = new.message_id;

  if v_message_user_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_MESSAGE_NOT_FOUND';
  end if;

  if v_message_user_id <> new.user_id then
    raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_OWNER_MISMATCH';
  end if;

  if v_message_author_type <> 'client' then
    raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_MESSAGE_NOT_CLIENT_AUTHORED';
  end if;

  if new.converted_by <> new.user_id then
    raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_ACTOR_MISMATCH';
  end if;

  if auth.uid() is distinct from new.converted_by then
    raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_ACTOR_NOT_AUTHENTICATED';
  end if;

  if new.project_update_id is not null then
    select project_update.user_id, project_update.project_id
      into v_update_user_id, v_update_project_id
      from public.project_updates as project_update
      where project_update.id = new.project_update_id;

    if v_update_user_id is null then
      raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_UPDATE_NOT_FOUND';
    end if;

    if v_update_user_id <> new.user_id then
      raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_UPDATE_NOT_OWNED';
    end if;

    if v_update_project_id <> v_message_project_id then
      raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_UPDATE_PROJECT_MISMATCH';
    end if;
  end if;

  if new.target_task_id is not null then
    select task.user_id, task.project_id
      into v_task_user_id, v_task_project_id
      from public.tasks as task
      where task.id = new.target_task_id;

    if v_task_user_id is null then
      raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_TASK_NOT_FOUND';
    end if;

    if v_task_user_id <> new.user_id then
      raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_TASK_NOT_OWNED';
    end if;

    if v_task_project_id is null
      or v_task_project_id <> v_message_project_id then
      raise exception using errcode = 'P0001', message = 'SHARE_CONVERSION_TASK_PROJECT_MISMATCH';
    end if;
  end if;

  return new;
end;
$$;

comment on function public.enforce_share_message_conversion_integrity() is
  'Rejects a conversion record whose owner does not match the converted message, whose message was not client-authored, whose converted_by is anyone other than the authenticated owner, or whose referenced Client Update or task belongs to another owner or another project. Performs no conversion itself: nothing here analyses a message, creates a project update, creates a task, changes any message status, or changes any project/task status.';

drop trigger if exists share_message_conversions_enforce_integrity
  on public.share_message_conversions;

create trigger share_message_conversions_enforce_integrity
before insert on public.share_message_conversions
for each row
execute function public.enforce_share_message_conversion_integrity();

-- =========================================================
-- 7. public.share_browser_sessions
--
-- Browser-session identity is immutable after insertion. Public paths may
-- advance last_seen_at and may revoke a session, but they may never rotate
-- a digest in place, extend expiry, clear revocation or move lifecycle
-- timestamps backwards.
-- =========================================================

create or replace function public.enforce_share_browser_session_integrity()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'UPDATE' then
    if new.session_digest is distinct from old.session_digest then
      raise exception using errcode = 'P0001', message = 'SHARE_SESSION_DIGEST_IMMUTABLE';
    end if;

    if new.digest_version is distinct from old.digest_version then
      raise exception using errcode = 'P0001', message = 'SHARE_SESSION_DIGEST_VERSION_IMMUTABLE';
    end if;

    if new.created_at is distinct from old.created_at then
      raise exception using errcode = 'P0001', message = 'SHARE_SESSION_CREATED_AT_IMMUTABLE';
    end if;

    if new.expires_at is distinct from old.expires_at then
      raise exception using errcode = 'P0001', message = 'SHARE_SESSION_EXPIRY_IMMUTABLE';
    end if;

    if new.last_seen_at is null
      or new.last_seen_at < old.last_seen_at then
      raise exception using errcode = 'P0001', message = 'SHARE_SESSION_LAST_SEEN_AT_DECREASE';
    end if;

    if old.revoked_at is not null
      and (
        new.revoked_at is null
        or new.revoked_at < old.revoked_at
      ) then
      raise exception using errcode = 'P0001', message = 'SHARE_SESSION_REVOCATION_IRREVERSIBLE';
    end if;
  end if;

  return new;
end;
$$;

comment on function public.enforce_share_browser_session_integrity() is
  'Rejects browser-session identity or expiry changes after insert, keeps last_seen_at monotonic, and makes revocation irreversible. A revoked session can never become usable again by clearing or backdating revoked_at.';

drop trigger if exists share_browser_sessions_enforce_integrity
  on public.share_browser_sessions;

create trigger share_browser_sessions_enforce_integrity
before insert or update on public.share_browser_sessions
for each row
execute function public.enforce_share_browser_session_integrity();

-- =========================================================
-- 8. public.share_session_grants
--
-- A grant must reference an existing browser session and an existing share
-- link (foreign keys guarantee existence, but the session's own expiry has
-- to be read to compare against), a grant may never outlive the browser
-- session that owns it, and a revoked grant may never be un-revoked: it
-- stays auditable and can never be silently promoted back to active.
-- =========================================================

create or replace function public.enforce_share_session_grant_integrity()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_session_expires_at timestamptz;
  v_session_revoked_at timestamptz;
  v_link_state text;
  v_link_expires_at timestamptz;
  v_link_configuration_version integer;
  v_link_requires_pin boolean;
  v_project_id uuid;
  v_project_deleted_at timestamptz;
begin
  if tg_op = 'UPDATE' then
    if new.browser_session_id is distinct from old.browser_session_id then
      raise exception using errcode = 'P0001', message = 'SHARE_GRANT_SESSION_IMMUTABLE';
    end if;

    if new.share_link_id is distinct from old.share_link_id then
      raise exception using errcode = 'P0001', message = 'SHARE_GRANT_LINK_IMMUTABLE';
    end if;

    if new.granted_configuration_version is distinct from old.granted_configuration_version then
      raise exception using errcode = 'P0001', message = 'SHARE_GRANT_CONFIGURATION_VERSION_IMMUTABLE';
    end if;

    if new.pin_verified_at is distinct from old.pin_verified_at then
      raise exception using errcode = 'P0001', message = 'SHARE_GRANT_PIN_VERIFICATION_IMMUTABLE';
    end if;

    if new.created_at is distinct from old.created_at then
      raise exception using errcode = 'P0001', message = 'SHARE_GRANT_CREATED_AT_IMMUTABLE';
    end if;

    if new.expires_at is distinct from old.expires_at then
      raise exception using errcode = 'P0001', message = 'SHARE_GRANT_EXPIRY_IMMUTABLE';
    end if;

    if old.revoked_at is not null then
      if new.revoked_at is null then
        raise exception using errcode = 'P0001', message = 'SHARE_GRANT_REVOCATION_IRREVERSIBLE';
      end if;

      if new.revoked_at is distinct from old.revoked_at then
        raise exception using errcode = 'P0001', message = 'SHARE_GRANT_REVOCATION_IMMUTABLE';
      end if;
    end if;

    return new;
  end if;

  select browser_session.expires_at, browser_session.revoked_at
    into v_session_expires_at, v_session_revoked_at
    from public.share_browser_sessions as browser_session
    where browser_session.id = new.browser_session_id;

  if v_session_expires_at is null then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_SESSION_NOT_FOUND';
  end if;

  if v_session_revoked_at is not null then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_SESSION_REVOKED';
  end if;

  if v_session_expires_at <= now() then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_SESSION_EXPIRED';
  end if;

  select
      link.state,
      link.expires_at,
      link.configuration_version,
      link.pin_hash is not null,
      project.id,
      project.deleted_at
    into
      v_link_state,
      v_link_expires_at,
      v_link_configuration_version,
      v_link_requires_pin,
      v_project_id,
      v_project_deleted_at
    from public.project_share_links as link
    left join public.projects as project
      on project.id = link.project_id
    where link.id = new.share_link_id;

  if v_link_state is null then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_LINK_NOT_FOUND';
  end if;

  if v_project_id is null then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_PROJECT_NOT_FOUND';
  end if;

  if v_project_deleted_at is not null then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_PROJECT_DELETED';
  end if;

  if v_link_state <> 'active' then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_LINK_NOT_ACTIVE';
  end if;

  if v_link_expires_at is not null and v_link_expires_at <= now() then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_LINK_EXPIRED';
  end if;

  if new.granted_configuration_version <> v_link_configuration_version then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_CONFIGURATION_VERSION_STALE';
  end if;

  if new.expires_at > v_session_expires_at then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_EXPIRY_EXCEEDS_SESSION';
  end if;

  if v_link_expires_at is not null and new.expires_at > v_link_expires_at then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_EXPIRY_EXCEEDS_LINK';
  end if;

  if v_link_requires_pin and new.pin_verified_at is null then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_PIN_VERIFICATION_REQUIRED';
  end if;

  if not v_link_requires_pin and new.pin_verified_at is not null then
    raise exception using errcode = 'P0001', message = 'SHARE_GRANT_PIN_VERIFICATION_UNEXPECTED';
  end if;

  return new;
end;
$$;

comment on function public.enforce_share_session_grant_integrity() is
  'On insert, rejects a per-link grant unless the browser session exists, is live and unrevoked; the share link exists, is active and unexpired; the linked project exists and is not deleted; the granted configuration version exactly matches the link; grant expiry fits within both session and link expiry; and PIN verification presence matches the link PIN requirement. On update, keeps grant identity, version, PIN verification, creation and expiry immutable and permits only initial revocation.';

