      expires_at = null,
      configuration_version = v_new_configuration_version
    where id = p_link_id
      and user_id = v_user_id;

  return jsonb_build_object(
    'linkId', p_link_id,
    'state', v_link_state,
    'expiresAt', null,
    'configurationVersion', v_new_configuration_version,
    'updatedAt', v_now
  );
end;
$$;

